from lib import *
S = SS('w97')
steps = [
    step("本地端口转发(ssh -L)。我在 paramiko 上自己实现了 SSH 服务器的转发功能。客户端在本地端口 19172 上监听,进来的每个连接被包进 SSH 的一个 direct-tcpip 通道,送到 SSH 服务器,再由服务器去连目标(端口 19639,一个回显服务器)。客户端连本地端口发 \"hello through the tunnel\",收到 \"ECHO:hello through the tunnel\"——目标的回显服务器加了 “ECHO:” 前缀,说明数据确实到了目标并返回。同时抓 SSH 服务器端口上的流量(此时 SSH 握手已经完成,只抓这一个转发连接期间的):共 432 字节,里面找不到明文 \"hello through the tunnel\",也找不到目标端口号的十进制文字——目标地址和端口放在加密的通道请求里。从线路上看,只是一条 SSH 连接。", t=tl(S(1)), mark=lidx(S(1), '客户端连本地', '同时抓 SSH 服务器端口'), done=lidx(S(1), '从线路上看只是一条 SSH 连接'), kv=KV([['本地监听', '19172(客户端)'], ['目标', '19639(SSH 服务器去连)'], ['回显', '"ECHO:hello through the tunnel"'], ['线路上', '432 字节,没有明文,没有目标端口']], ['线路上'])),
    step("远程端口转发(ssh -R)。客户端发 tcpip-forward 全局请求,要求服务器在它的端口 19518 上监听;之后外部连 19518 发 \"knock knock\",收到 \"CLIENT-SIDE:knock knock\"——连接经 SSH 回到了客户端这一侧的目标(端口 19585,前缀 CLIENT-SIDE:)。这个方向用来把“里面”(客户端那边)的服务暴露到服务器能被访问的地方。注意两个方向的对称:-L 是客户端发起通道、服务器连目标;-R 是服务器发起通道(forwarded-tcpip)、客户端连目标。", t=tl(S(2)), mark=lidx(S(2), '请求服务器在'), done=lidx(S(2), '请求服务器在'), kv=KV([['-R 全局请求', 'tcpip-forward(服务器监听 19518)'], ['外部连 19518', '服务器开 forwarded-tcpip 通道给客户端'], ['回显', '"CLIENT-SIDE:knock knock"']], ['-R 全局请求'])),
    step("一条 SSH 连接承载多个转发连接(多路复用):通过同一个隧道同时开 20 个连接,各自发一条不同的消息(msg-00 到 msg-19),20 个连接全部收到自己的回显,20 / 20 正确,没有串线。它们全部走同一条到 SSH 服务器的 TCP 连接(这一点是 SSH 的设计:每个转发连接是一个通道,通道在同一个 TCP 连接里按通道号复用——我是从实现方式知道的,没有单独计数)。", t=tl(S(3)), mark=lidx(S(3), '20 个并发连接各自收到'), done=lidx(S(3), '20 个并发连接各自收到'), b=bars([['并发转发连接', 20, '20'], ['回显正确', 20, '20']], 20, mark=[], done=[0, 1]), kv=KV([['并发通道', '20 个'], ['正确回显', '20 / 20'], ['到 SSH 服务器的 TCP', '1 条(设计如此)']], ['正确回显'])),
    step("隧道的代价。lo0 上传 2 MB:直连中位 1 ms;经 SSH 隧道中位 12 ms(约 173 MB/s)——慢了一个数量级,但绝对值不大(paramiko,不代表 OpenSSH)。然后只在 SSH 那一条 TCP 连接上加 netlab(每方向 25 ms):0% 丢包时,直连 [252, 305] ms,经隧道 [211, 157] ms——隧道没有更慢,反而更快(我猜是因为内层连接在本机,数据先一下子灌进 SSH 的发送窗口,而直连要经历 TCP 慢启动;这只是推测)。2% 丢包时,直连 [615, 803] ms,经隧道 [1015, 1163] ms,隧道约慢 1.5 倍。需要注意:这里只有 SSH 那一条 TCP 受损,内层连接没有受损,所以这还不是严格意义上的“TCP 套 TCP”;每个条件只测了 2 次,只能当作量级参考。", t=tl(S(4)), mark=lidx(S(4), 'netlab 每方向 25 ms、丢包 2%', 'netlab 每方向 25 ms、丢包 0%'), done=lidx(S(4), '直连 2 MB', '经隧道 2 MB'), b=bars([['0% 丢包 直连', 305, '[252, 305] ms'], ['0% 丢包 隧道', 211, '[211, 157] ms'], ['2% 丢包 直连', 803, '[615, 803] ms'], ['2% 丢包 隧道', 1163, '[1015, 1163] ms']], 1163, mark=[3], done=[0, 1, 2]), kv=KV([['回环 2 MB', '直连 1 ms,隧道 12 ms'], ['25 ms + 0% 丢包', '直连 252/305,隧道 211/157'], ['25 ms + 2% 丢包', '直连 615/803,隧道 1015/1163']], ['25 ms + 2% 丢包'])),
]
A = mkartw('w97', 97, '网络协议,SSH,端口转发,隧道,direct-tcpip,tcpip-forward,真实验证,动画演示',
    '在 paramiko 上实现并实测 SSH 端口转发:-L 经 direct-tcpip 通道把数据送到目标并回来,线路上 432 字节里没有明文和目标端口;-R 用 tcpip-forward 把连接送回客户端;20 个并发转发连接全部正确;隧道比直连 12 ms 对 1 ms,2% 丢包下约慢 1.5 倍。',
    'SSH 不只是远程登录:它还能当隧道。-L 把本地端口变成远处的服务,-R 把近处的服务暴露到远处。这篇在本机实现一个会转发的 SSH 服务器,验证两个方向的转发、多个连接怎么共用一条 SSH 连接,以及隧道的代价。',
    [('432 字节', '一次本地转发连接期间 SSH 服务器端口上的流量,里面找不到明文和目标端口'), ('20 / 20', '同一个隧道并发 20 个转发连接,各自收到自己的回显'), ('1015~1163 vs 615~803 ms', '2% 丢包下经隧道与直连传 2 MB 的耗时(各 2 次)')],
    [('-L 本地转发', '<p>客户端监听本地端口,每个连接变成一个 direct-tcpip 通道,由服务器去连目标。目标地址只出现在加密的通道请求里。</p>'),
     ('-R 远程转发', '<p>客户端发 tcpip-forward 请求,服务器监听并把每个进来的连接通过 forwarded-tcpip 通道送回客户端。</p>'),
     ('多路复用', '<p>所有转发连接是同一条 SSH 连接里的不同通道。</p>'),
     ('代价', '<p>多一层加解密和窗口控制;受损的链路上隧道约慢 1.5 倍;0% 丢包的延迟链路上没有更慢。</p>')],
    steps,
    [ENV_W + '。转发功能是我用 paramiko 5.0.0 自己实现的服务器端和客户端(没有用 OpenSSH),全在本机;密钥临时生成;第四节每个条件只测 2 次,只有 SSH 那一条 TCP 在 netlab 范围内(其余端口刻意放在范围外),所以不是严格的 TCP 套 TCP;吞吐数字是 paramiko 的,不代表 OpenSSH',
     '没有验证:动态转发 -D(SOCKS 代理,下一部分讲 SOCKS5);ProxyJump 和多跳;OpenSSH 的 ControlMaster 复用;GatewayPorts 与绑定地址的安全影响;通道窗口大小对吞吐的影响;真正的 TCP 套 TCP(内外层都受损)'],
    'SSH 端口转发')
